source:
(shader) => {
    shader.uniforms.npcBlink = blink;
    shader.vertexShader = 'varying vec3 npcFacePosition;\n' + shader.vertexShader.replace('#include <begin_vertex>', '#include <begin_vertex>\nnpcFacePosition=position;');
    shader.fragmentShader = 'uniform float npcBlink;\nvarying vec3 npcFacePosition;\n' + shader.fragmentShader.replace('#include <map_fragment>', `#include <map_fragment>
     if(npcBlink>0.0 && npcFacePosition.z>.08){
      float eyeX=npcFacePosition.x<0.0?-.093:.085;
      vec2 eye=(npcFacePosition.xy-vec2(eyeX,1.434))/vec2(.043,.044);
      float area=1.0-smoothstep(.88,1.0,length(eye));
      float opening=(1.0-npcBlink)*1.12;
      float lid=smoothstep(opening-.045,opening+.045,abs(eye.y));
      lid=mix(lid,1.0,smoothstep(.95,1.0,npcBlink));
      vec3 skin=vec3(.55,.43,.32);
      float crease=(1.0-smoothstep(.015,.085,abs(eye.y)))*smoothstep(.9,1.0,npcBlink);
      skin*=1.0-crease*.38;
      diffuseColor.rgb=mix(diffuseColor.rgb,skin,area*lid);
     }`);
  }

